{
  "name": "numerai-kedro-claude",
  "build": {
    "dockerfile": "Dockerfile",
    "context": ".."
  },
  "features": {
    "ghcr.io/devcontainers/features/common-utils:2": {
      "installZsh": "true",
      "configureZshAsDefaultShell": "true",
      "username": "vscode",
      "upgradePackages": "true"
    },
    "ghcr.io/devcontainers/features/aws-cli:1": {
      "version": "latest"
    },
    "ghcr.io/devcontainers/features/github-cli:1": {}
  },
  "remoteUser": "vscode",
  "updateRemoteUserUID": true,
  // Runs on the HOST before the container is created/built: guarantees .env
  // exists and is aligned with .env.example (adds any new keys, never touches
  // existing values, fills CLAUDE_CODE_OAUTH_TOKEN from the host env if set).
  // If the token is still empty and a terminal is attached, it offers to run
  // `claude setup-token` right there (15s auto-skip), so the token exists
  // BEFORE docker reads --env-file and the first boot is already authed.
  "initializeCommand": "bash .devcontainer/sync-env.sh",
  // Load repo-root .env into the container's environment at boot, so secrets
  // like CLAUDE_CODE_OAUTH_TOKEN / ANTHROPIC_API_KEY are present for every
  // process (Claude Code included) without a host-shell export. sync-env.sh
  // above creates the file, so `docker run` never fails on a missing .env.
  "runArgs": ["--env-file", "${localWorkspaceFolder}/.env"],
  "workspaceFolder": "/workspaces/${localWorkspaceFolderBasename}",
  "mounts": [
    // Shared shell config (zshrc / starship / tmux) — single source of truth
    // from the host's ~/env checkout (https://github.com/neeland/env).
    "source=${localEnv:HOME}/env,target=/home/vscode/env,type=bind,consistency=cached,readonly",
    "source=${localEnv:HOME}/.aws,target=/home/vscode/.aws,type=bind,consistency=cached,readonly",
    "source=${localEnv:HOME}/.ssh,target=/home/vscode/.ssh,type=bind,consistency=cached",
    "source=${localEnv:HOME}/.gitconfig,target=/home/vscode/.gitconfig,type=bind,consistency=cached"
  ],
  "remoteEnv": {
    "AWS_PROFILE": "default",
    "PYTHONDONTWRITEBYTECODE": "1",
    "PATH": "${containerEnv:PATH}:/home/vscode/.local/bin",
    "UV_LINK_MODE": "copy",
    // MCP secrets are pulled from your HOST environment (never committed).
    // Export EXA_API_KEY and NUMERAI_MCP_AUTH on your machine before opening the container.
    "EXA_API_KEY": "${localEnv:EXA_API_KEY}",
    "NUMERAI_MCP_AUTH": "${localEnv:NUMERAI_MCP_AUTH}"
  },
  "customizations": {
    "vscode": {
      "extensions": [
        "ms-python.python",
        "ms-python.vscode-pylance",
        "ms-toolsai.jupyter",
        "charliermarsh.ruff",
        "redhat.vscode-yaml",
        "tamasfe.even-better-toml",
        "AmazonWebServices.aws-toolkit-vscode",
        "bierner.markdown-mermaid",
        "zaaack.markdown-editor",
        "ms-toolsai.datawrangler",
        "kanaries.graphic-walker-vscode-plugin",
        "Anthropic.claude-code"
      ],
      "settings": {
        "terminal.integrated.defaultProfile.linux": "zsh",
        "editor.formatOnSave": true,
        "python.analysis.typeCheckingMode": "basic"
      }
    }
  },
  "postCreateCommand": "bash .devcontainer/post-create.sh"
}

